    UNION
    SELECT g.away_id FROM phase p JOIN game g ON g.phase_id = p.id WHERE p.championship_id = target_championship
  ) x ORDER BY x.team_id
  LOOP PERFORM enqueue_team_profile(target_id); END LOOP;
